sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading) {

        g_form.setDisplay('bubble_id', false); //hiding Bubble ID from Form
        //to Display and hide add attribute only for active records
        if ((g_form.getValue('state') == 1 || g_form.getValue('state') == 2 || g_form.getValue('state') == 18)) {
            g_form.setDisplay('add_attribute', true);
        } else {
            g_form.setDisplay('add_attribute', false);
        }
        //to Display and hide add attribute only for active records

        //hide attributes for manual incoming
        if (g_form.getValue('case_type') == 'manual_incoming') {
            g_form.setDisplay('add_attribute', false);
        }
        //hide attributes for manual incoming

        //Bubble Creation info
        g_form.setDisplay('participant_id', true);
        if ((!g_form.isNewRecord()) && (g_form.getValue('participant_id') == "")) {
            g_form.setValue('draft_comments', ""); //clearing draft comments for the first population of participant ID
            g_form.addSuggestionMessage('Bubble Creation is in Progress... Please wait');
        } else {
            g_form.clearMessages();
        }
        g_form.setDisplay('participant_id', false);
        //Bubble Creation info

        //retriving stored attributes stored in system property
        var gr = new GlideAjax("x_hsb11_mss_taskiz.MSSTaskizeUtils");
        gr.addParam('sysparm_name', 'getAttributesList');
        gr.getXMLAnswer(getAttributes);
        return;
        //retriving stored attributes stored in system property

    }

    if ((g_form.getValue('state') == 1 || g_form.getValue('state') == 2 || g_form.getValue('state') == 18)) {
        removeAttributes('add_attribute', newValue, true);
    }



    //dynamically remove the attributes once user selects a sepcific attributes
    function removeAttributes(dependentField, newValue, action) {
        g_form.setDisplay(newValue, action);
        g_form.clearValue(dependentField);
        if ((newValue != '') && (newValue != undefined) && (newValue != null)) {
            g_form.removeOption(dependentField, newValue);
        }
    }
    //dynamically remove the attributes once user selects a sepcific attributes



    //addition of dynamic options to the Add attribute + hiding of all fields which are empty on load
    function getAttributes(response) {
        var dependentValues = response.split(",");
        var allAttributes = [];
        for (var j = 0; j < dependentValues.length; j++) {
            allAttributes.push(dependentValues[j].split(":")[1]);
        }
        //Call the function to add the items to the field
        createDependentOptions('add_attribute', dependentValues, true);
        allAttributes.forEach(function(element) {
            if ((g_form.hasField(element)) && (g_form.getValue(element) == "" || g_form.getValue(element) == 'false')) {
                g_form.setDisplay(element, false);
            }
        });
    }
    //addition of dynamic options to the Add attribute + hiding of all fields which are empty on load


    //dynamically adding options to the new field
    function createDependentOptions(dependentField, dependentValues, includeNone) {
        var index = 0;
        if (includeNone) {
            g_form.addOption(dependentField, '', '-- None --', 0);
            index++;
        }
        if (dependentValues != '') {
            for (var i = 0; i < dependentValues.length; i++) {
                if (g_form.getValue(dependentValues[i].split(':')[1]) == "") { //restricting option addition if already on form
                    g_form.addOption(dependentField, dependentValues[i].split(':')[1], dependentValues[i].split(':')[0], i + index);
                }
            }
        }
    }
    //dynamically adding options to the new field
}
